export function getScenarioScript(id: string, C: ThemeColors, mode?: 'career' | 'social'): ScenarioScript | undefined {
  if (id === 'onboarding-cafe' && mode) {
    return getScenarioScripts(C)[`${id}-${mode}`];
  }
  return getScenarioScripts(C)[id];
}
